import {readdir,readFile,mkdir,writeFile}from'node:fs/promises';import{gzipSync}from'node:zlib';import{execFileSync}from'node:child_process';
const baseline=process.argv[2]??'../baseline',candidate=process.argv[3]??'.',reports={};
for(const[label,dir]of[['baseline',baseline],['candidate',candidate]]){const names=await readdir(`${dir}/dist/assets`),assets=[];for(const name of names.filter(n=>/\.(js|css)$/.test(n))){const bytes=await readFile(`${dir}/dist/assets/${name}`);assets.push({name,bytes:bytes.length,gzip:gzipSync(bytes).length});}const sum=fn=>assets.filter(fn).reduce((n,a)=>n+a.gzip,0);reports[label]={commit:execFileSync('git',['-C',dir,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),build:JSON.parse(await readFile(`${dir}/dist/build.json`,'utf8')),initialGzipBytes:sum(a=>a.name.startsWith('index-')&&a.name.endsWith('.js')),allJsGzipBytes:sum(a=>a.name.endsWith('.js')),cssGzipBytes:sum(a=>a.name.endsWith('.css')),assets};}
const limits={initialGzipBytes:104448,allJsGzipBytes:148480,cssGzipBytes:24576},failures=Object.entries(limits).filter(([key,max])=>reports.candidate[key]>max).map(([key,max])=>({key,max,actual:reports.candidate[key]}));await mkdir('artifacts/nextgen',{recursive:true});await writeFile('artifacts/nextgen/bundle-comparison.json',JSON.stringify({environment:{node:process.version,compression:'node:zlib gzipSync defaults'},reports,limits,failures},null,2));console.log(JSON.stringify({baseline:reports.baseline,candidate:reports.candidate,failures},null,2));if(failures.length)process.exitCode=1;
